class Completed {

    public int sumNumbers(TreeNode root) {

        return dfs(root, 0);
    }

    private int dfs(TreeNode node, int current) {

        if (node == null) {
            return 0;
        }

        int next = current * 10 + node.val;

        if (node.left == null && node.right == null) {
            return next;
        }

        return dfs(node.left, next) + dfs(node.right, next);
    }
}

